import React, { useState, useEffect, useRef } from "react";
import { useNavigate } from "react-router-dom";
import '../styles/index.css';
import HyOrderForm from './HyOrderForm';
import { config } from '../config/config';

export default function HyOrderCalculator() {
  const navigate = useNavigate();
  const [formData, setFormData] = useState({
    serviceGen: "gen2",
    paymentType: "postpaid",
    devicePeriod: "3year",
    servicePeriod: "3year",
    menu10: 0,
    display10: 0,
    display15: 0,
    cardReaderType: "basic",
    cardReader: 0,
    discountOption: "none",
  });
  const [prepaidAmount, setPrepaidAmount] = useState(0);
  const [includeVAT, setIncludeVAT] = useState(false);
  const [resultData, setResultData] = useState({
    total: null,
    deviceCost: 0,
    serviceCost: 0,
    cardCost:   0,
    lumpsum: null,
    monthly: null,
  });
  const [lumpsumOnly, setLumpsumOnly] = useState(null);
  const [monthlyOnly, setMonthlyOnly] = useState(null);
  const resultRef = useRef(null);

  // 선불형일 때 카드리더 수량은 메뉴판 10인치 수량만 반영
  useEffect(() => {
    if (formData.paymentType === "prepaid") {
      setFormData(prev => ({ ...prev, cardReader: prev.menu10 }));
    }
  }, [formData.paymentType, formData.menu10]);

  const handleChange = e => {
    const { name, value, type, checked } = e.target;
    if (formData.paymentType === 'prepaid' && name === 'cardReader') {
      setFormData(prev => ({ ...prev, cardReader: prev.menu10 }));
      return;
    }
    if (type === 'checkbox') {
      setFormData(prev => ({ ...prev, [name]: checked }));
    } else {
      const numFields = ["menu10", "display10", "display15", "cardReader"];
      setFormData(prev => ({
        ...prev,
        [name]: numFields.includes(name) ? Number(value) : value
      }));
    }
  };

  const handleCalculate = () => {
    const dp = formData.devicePeriod;
    const sp = formData.servicePeriod;
    const sg = formData.serviceGen;

    // 단말 금액
    const m10 = formData.menu10 * (config[`price_menu10_${sg}_${dp}`] || 0);
    const d10 = formData.display10 * (config[`price_display10_${sg}_${dp}`] || 0);
    const d15 = formData.display15 * (config[`price_display15_${sg}_${dp}`] || 0);

    // 카드리더(선불)
    const readerRate = config[`price_cardreader_${formData.cardReaderType}`] || 0;
    let cardCost = formData.paymentType === "prepaid"
      ? formData.cardReader * readerRate
      : 0;

    const totalTerms = formData.menu10 + formData.display10 + formData.display15;

    // 서비스 요금
    const serviceRate = config[`price_service_${sg}_${sp}`] || 0;
    const serviceLump = config[`price_service_${sg}_${sp}_lumpsum`] || 0;

    let total = 0;

    // 선납(서비스약정에 lumpsum 포함)
    if (sp.includes('lumpsum')) {
      const lumpsum = 0 /* 단말/알림판 일시불면 0 */ + serviceLump * totalTerms;
      const monthly = formData.paymentType === 'prepaid' ? cardCost : 0;
      if (includeVAT) {
        setLumpsumOnly(Math.round(lumpsum * 1.1));
        setMonthlyOnly(Math.round(monthly * 1.1));
      } else {
        setLumpsumOnly(lumpsum);
        setMonthlyOnly(monthly);
      }
      total = (includeVAT ? Math.round(lumpsum * 1.1) : lumpsum)
            + (includeVAT ? Math.round(monthly * 1.1) : monthly);
      // clear resultData
      setResultData({ total: null, deviceCost: 0, serviceCost: 0, lumpsum, monthly });

    } else {
    // 1) 월 단말 요금(이미 config 값이 월 요금입니다)
     let deviceMonthly = m10 + d10 + d15;
     // 2) 선납 입금이 있으면, 매월 차감할 금액은 (prepaidAmount ÷ 36)
     deviceMonthly = deviceMonthly - (prepaidAmount / 36);
   
    // 3) 서비스 월정액 요금
    let serviceCost  = serviceRate * totalTerms;

      // VAT 적용 시엔 월별 금액에도 VAT 포함
    if (includeVAT) {
      deviceMonthly = Math.round(deviceMonthly * 1.1);
      serviceCost  = Math.round(serviceCost  * 1.1);
      cardCost = Math.round(cardCost * 1.1);
    }

    // 최종 월 예상 총액 = 단말(월) + 서비스(월) + 카드리더기(총액)
    const monthlyTotal = deviceMonthly + serviceCost + cardCost;

    // 상태 저장
    setLumpsumOnly(null);
    setMonthlyOnly(null);
    setResultData({
     total:      monthlyTotal,
     deviceCost: deviceMonthly,
     serviceCost,
     cardCost,          // ← 새롭게 추가된 카드리더기 비용
     lumpsum:    null,
     monthly:    null,
    });
      total = monthlyTotal;
    }

    setTimeout(() => {
      resultRef.current?.scrollIntoView({ behavior: 'smooth', block: 'start' });
    }, 100);
  };

  return (
    <div className="max-w-xl mx-auto p-4 bg-white shadow rounded-xl">
      <h2 className="text-xl font-bold mb-4 text-center">KT 하이오더 계산기</h2>
      <p className="mt-2 text-base font-bold text-red-500">
        주의! 본 견적은 가 견적이오니, 정확한 견적은 필히 추가로 확인하셔야 합니다.
      </p>
      <div className="grid grid-cols-2 gap-4 mb-4">
        <div>
          <label className="block text-sm font-medium">하이오더 세대</label>
          <select
            name="serviceGen"
            className="mt-1 w-full border rounded p-2"
            value={formData.serviceGen}
            onChange={handleChange}
          >
            <option value="gen1">1세대 (기본: {config.price_service_gen1_3year.toLocaleString()}원)</option>
            <option value="gen2">2세대 (기본: {config.price_service_gen2_3year.toLocaleString()}원)</option>
          </select>
        </div>
        <div>
          <label className="block text-sm font-medium">결제 방법</label>
          <select
            name="paymentType"
            className="mt-1 w-full border rounded p-2"
            value={formData.paymentType}
            onChange={handleChange}
          >
            <option value="postpaid">후불형</option>
            <option value="prepaid">선불형</option>
          </select>
        </div>
      </div>

      {/* Form */}
      <HyOrderForm
        formData={formData}
        handleChange={handleChange}
        prepaidAmount={prepaidAmount}
        setPrepaidAmount={setPrepaidAmount}
        includeVAT={includeVAT}
        setIncludeVAT={setIncludeVAT}
        handleCalculate={handleCalculate}
      />

      {/* 결과 */}
 <div ref={resultRef} className="mt-4">
   {formData.servicePeriod.includes('lumpsum') ? (
     <>
       {/* 선납(서비스 lumpsum)인 경우 */}
       <div className="font-semibold">
         일시불 총액: {lumpsumOnly?.toLocaleString() || 0}원
       </div>
       <div className="font-semibold">
         선납 요금:{' '}
         {(config[`price_service_${formData.serviceGen}_${formData.servicePeriod}`] || 0)
           .toLocaleString()}원
       </div>
       <div className="font-semibold">
         월 요금: {monthlyOnly?.toLocaleString() || 0}원
       </div>
     </>
   ) : resultData.total != null ? (
     <>
       <div className="font-semibold">
         단말 요금: {resultData.deviceCost.toLocaleString("ko-KR", {
        maximumFractionDigits: 0
  })}원
       </div>
       {formData.paymentType === 'prepaid' && (
         <div className="font-semibold">
           카드리더기 요금: {resultData.cardCost.toLocaleString("ko-KR", {
       maximumFractionDigits: 0
  })}원
         </div>
       )}
       <div className="font-semibold">
         서비스 요금: {resultData.serviceCost.toLocaleString("ko-KR", {
       maximumFractionDigits: 0
  })}원
       </div>
       <div className="font-semibold">
         총 월 예상 요금: {resultData.total.toLocaleString("ko-KR", {
       maximumFractionDigits: 0
  })}원
       </div>
     </>
   ) : null}
 </div>

      <div className="mt-6 w-full text-center">
        <button
          onClick={() => navigate('/')}
          className="w-full px-4 py-2 bg-gray-200 rounded hover:bg-gray-300"
        >
          메인 메뉴로 돌아가기
        </button>
      </div>
    </div>
  );
}
